const recipes=[{id:'potion',icon:'🧪',name:'Tónico de hierbas',desc:'2 hierbas · recupera salud',need:{herb:2}},{id:'sword',icon:'🗡️',name:'Espada de roble',desc:'3 madera + 2 piedra · +4 ATQ',need:{wood:3,stone:2}},{id:'wall',icon:'🪵',name:'Valla de madera',desc:'3 madera · construcción',need:{wood:3}},{id:'fiber',icon:'🧵',name:'Vendaje de fibra',desc:'2 hierbas + 1 madera · +20 salud',need:{herb:2,wood:1}}];function canCraft(r){return Object.entries(r.need).every(([id,n])=>(item(id)?.qty||0)>=n)}function renderRecipes(){$('#recipeList').innerHTML=recipes.map(r=>`<div class="recipe"><div class="recipe-icon">${r.icon}</div><div><b>${r.name}</b><p>${r.desc}</p></div><button data-recipe="${r.id}" ${canCraft(r)?'':'disabled'}>CREAR</button></div>`).join('');$$('[data-recipe]').forEach(b=>b.onclick=()=>craft(b.dataset.recipe))}
