function openLegacy(){modal('El legado de tu casa','Tu historia no termina aquí. La memoria del linaje permanece.',`<div class="world-card"><div class="world-art">🌿<span>✦</span>🏡</div><b>Casa del Alba · Generación ${S.lineage}</b><p>Un linaje joven, ligado al claro y a los primeros pactos del valle.</p></div><div class="modal-feature">Modo legado roguelike opcional: al fundar una nueva generación conservarás la reputación, las mejoras del hogar y un recuerdo heredado. El personaje y la mochila comienzan de nuevo.</div><p style="font-size:10px;color:#788479">Recompensas de legado: +${S.lineage} monedas iniciales · +${Math.min(S.lineage,3)} reputación de Custodios.</p>`,`<div class="modal-actions"><button class="plain-btn" id="cancelLegacy">VOLVER</button><button class="primary-btn" id="newLegacy">FUNDAR GENERACIÓN</button></div>`);$('#cancelLegacy').onclick=()=>$('#modalRoot').innerHTML='';$('#newLegacy').onclick=()=>{S.lineage++;S.hp=S.maxHp=100;S.level=1;S.xp=0;S.gold=12+S.lineage;S.x=19.5;S.y=12.5;S.inventory=[{id:'berry',name:'Bayas silvestres',icon:'🫐',qty:3,desc:'Dulces bayas azuladas. Recuperan 12 de salud.'},{id:'wood',name:'Madera',icon:'🪵',qty:2,desc:'Madera ligera, útil para construir y fabricar.'},{id:'herb',name:'Hierbas',icon:'🌿',qty:2,desc:'Hierbas aromáticas con propiedades curativas.'}];S.quests=[];S.rep.grove+=2;entities.filter(e=>e.type==='enemy').forEach(e=>{e.alive=true;e.hp=e.maxHp});$('#modalRoot').innerHTML='';renderAll();notify(`Comienza la generación ${S.lineage}. El legado de tu casa te acompaña.`)}}
function openBuild(){S.buildMode=!S.buildMode;$('#buildBtn').textContent=S.buildMode?'✓ SALIR DE CONSTRUCCIÓN':'⌂ MODO CONSTRUCCIÓN';toast(S.buildMode?'Modo construcción: toca un espacio de hierba para colocar una valla (3 maderas).':'Modo construcción cerrado.')}
function worldMap(){modal('Mapa del valle','Los senderos conocidos de tu aventura.',`<div class="world-card"><div class="world-art" style="height:165px;font-size:28px">🌲　🌿　🏡　🌲<span>☁</span></div><b>Claro del Alba</b><p>Tu hogar está aquí. Al este, los lobos rondan el lindero. Habla con los habitantes para descubrir nuevos caminos.</p></div><div class="world-facts"><div><span>⌖</span><div><b>Claro del Alba</b><small>Tu ubicación actual · zona segura</small></div></div><div><span>☼</span><div><b>Próximo cambio</b><small id="mapWeather">El mundo cambia con el día y el clima.</small></div></div></div>`,'<div class="modal-actions"><button class="primary-btn" id="mapClose">CERRAR MAPA</button></div>');$('#mapClose').onclick=()=>$('#modalRoot').innerHTML=''}
function useSelected(){let it=item(S.selected);if(!it){toast('Selecciona un objeto primero.');return}if(it.id==='berry'){S.hp=Math.min(S.maxHp,S.hp+12);it.qty--;toast('Comiste bayas silvestres. +12 salud.')}else if(it.id==='potion'){S.hp=Math.min(S.maxHp,S.hp+35);it.qty--;toast('Tónico utilizado. +35 salud.')}else if(it.id==='fiber'){S.hp=Math.min(S.maxHp,S.hp+20);it.qty--;toast('Vendaje aplicado. +20 salud.')}else{toast('Este objeto se utiliza al fabricar o explorar.');return}S.inventory=S.inventory.filter(a=>a.qty>0);S.selected=S.inventory[0]?.id||null;renderAll()}
