 function attack(e){if(S.tool!=='sword'&&S.tool!=='hand'&&S.tool!=='axe'&&S.tool!=='pickaxe'){toast('Equipa un arma para combatir.');return}let damage=S.attack+(S.tool==='sword'?3:0);e.hp-=damage;S.stamina=Math.max(0,S.stamina-10);toast(`Golpeaste a ${e.name} por ${damage} daño.`);if(e.hp<=0){e.alive=false;S.xp+=22;S.gold+=5;S.rep.wild+=1;addItem('fiber',1);changeQuestProgress('wolf');toast(`¡${e.name} huyó! +22 XP · +5 monedas`);if(S.xp>=S.level*50){S.xp-=S.level*50;S.level++;S.maxHp+=10;S.hp=S.maxHp;S.attack++;toast(`¡Subiste al nivel ${S.level}!`)}}else{S.hp=Math.max(0,S.hp-e.attack);if(S.hp<=0){S.hp=1;S.gold=Math.max(0,S.gold-3);S.x=S.home?19:19.5;S.y=21;toast('El lobo te venció. Despertaste en el refugio (−3 monedas).')}}renderAll()}
