 function dialogueChoice(c){if(c==='quest'){createQuest();$('#dialogueText').textContent='Gracias, viajera. La primera tarea es sencilla: observa, recoge y cuida el valle. Vuelve cuando tengas noticias.';$('#dialogueChoices').innerHTML='<button data-choice="bye">Me pondré en marcha</button>';$$('[data-choice]').forEach(b=>b.onclick=()=>closeDialogue())}else if(c==='lore'){$('#dialogueText').textContent='Al norte se extiende el Robledal; al este, las colinas de los lobos. Dicen que las estaciones escuchan a quienes viven aquí.';$('#dialogueChoices').innerHTML='<button data-choice="bye">Gracias por contármelo</button>';$$('[data-choice]').forEach(b=>b.onclick=()=>closeDialogue())}else if(c==='trade'){let wood=item('wood'),stone=item('stone'),total=0;if(wood&&wood.qty>=2){wood.qty-=2;total+=8}if(stone&&stone.qty>=1){stone.qty-=1;total+=5}S.inventory=S.inventory.filter(i=>i.qty>0);if(total){S.gold+=total;S.rep.guild+=2;S.xp+=8;renderAll();$('#dialogueText').textContent=`¡Buen trabajo! Te pago ${total} monedas. El Gremio de Brumaria recordará tu ayuda.`}else $('#dialogueText').textContent='No tienes suficiente material. Tráeme 2 maderas o 1 piedra y te pagaré.';$('#dialogueChoices').innerHTML='<button data-choice="bye">Entendido</button>';$$('[data-choice]').forEach(b=>b.onclick=()=>closeDialogue())}else if(c==='craft'){$('#dialogueText').textContent='Usa el Taller de campo en tu mochila. Las recetas se desbloquean mientras exploras; la espada de roble te ayudará contra los lobos.';$('#dialogueChoices').innerHTML='<button data-choice="bye">Lo intentaré</button>';$$('[data-choice]').forEach(b=>b.onclick=()=>{closeDialogue();setTab('crafting')})}else closeDialogue()}
