function tick(now){let dt=Math.min(.05,(now-last)/1000||0);last=now;if(!S.dialogue){let dx=0,dy=0;if(keys.w||keys.arrowup||touchDir==='up')dy--;if(keys.s||keys.arrowdown||touchDir==='down')dy++;if(keys.a||keys.arrowleft||touchDir==='left')dx--;if(keys.d||keys.arrowright||touchDir==='right')dx++;if(dx&&dy){dx*=.707;dy*=.707}if(dx||dy){let speed=3.35*dt,nx=S.x+dx*speed,ny=S.y+dy*speed;if(!blocked(nx,S.y))S.x=nx;if(!blocked(S.x,ny))S.y=ny;S.stamina=Math.min(100,S.stamina+dt*1.8)}else S.stamina=Math.min(100,S.stamina+dt*4);S.x=Math.max(2.2,Math.min(W-2.2,S.x));S.y=Math.max(2.2,Math.min(H-2.2,S.y));S.minute+=dt*8;if(S.minute>=1440){S.minute-=1440;S.day++;if(Math.random()<.42){let ws=['Despejado','Lluvia','Nublado'];S.weather=ws[Math.floor(Math.random()*ws.length)];S.weatherIcon={Despejado:'☀',Lluvia:'☂',Nublado:'☁'}[S.weather];$('#weatherText').textContent=S.weather;$('#weatherIcon').textContent=S.weatherIcon}}let hr=Math.floor(S.minute/60),mn=Math.floor(S.minute%60);$('#clock').textContent=String(hr).padStart(2,'0')+':'+String(mn).padStart(2,'0');$('#dayLabel').textContent=`DÍA ${S.day} · ${hr<6?'NOCHE':hr<12?'MAÑANA':hr<18?'TARDE':'NOCHE'}`;$('#timeIcon').textContent=hr>=20||hr<5?'☾':hr>=17?'◒':'☼';for(let foe of entities.filter(e=>e.type==='enemy'&&e.alive)){let d=Math.hypot(foe.x-S.x,foe.y-S.y);if(d<5&&d>1.3){let step=dt*.45;foe.x+=(S.x-foe.x)/d*step;foe.y+=(S.y-foe.y)/d*step}if(d<1.1){foe.cool=(foe.cool||0)-dt;if(foe.cool<=0){S.hp=Math.max(1,S.hp-foe.attack);foe.cool=2.2;renderStats();toast(`${foe.name} te hirió. Aléjate o contraataca.`)}}}if(Math.floor(now/1500)!==Math.floor((now-dt*1000)/1500))renderStats()}draw();requestAnimationFrame(tick)}
